"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type KeyboardEvent, type ReactNode, useId, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a number field. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export interface NumberFieldProps {
  label: ReactNode;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  className?: string;
}

type Direction = 1 | -1;

// Damping 46 is 2 × √520, rounded up: critically damped, so digits land without overshoot.
const ROLL_SPRING: Transition = { type: "spring", stiffness: 520, damping: 46, mass: 1 };
const INSTANT: Transition = { duration: 0 };

// The direction travels through AnimatePresence's `custom`, because a leaving
// digit keeps the props of its last render and would exit the old way.
const ROLL = {
  enter: (dir: Direction) => ({ y: `${dir * 100}%`, opacity: 0 }),
  shown: { y: 0, opacity: 1 },
  leave: (dir: Direction) => ({ y: `${-dir * 100}%`, opacity: 0 }),
};

function MinusGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="M3.5 8h9" strokeLinecap="round" />
    </svg>
  );
}

function PlusGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="M3.5 8h9M8 3.5v9" strokeLinecap="round" />
    </svg>
  );
}

const STEP_BUTTON =
  "grid size-11 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full text-muted-foreground outline-none hover:bg-muted hover:text-foreground active:scale-90 disabled:cursor-not-allowed disabled:opacity-40 motion-safe:transition sm:size-9";

/**
 * Enters a whole number by typing, by the minus and plus buttons, or by arrow
 * keys. Each digit that changes rolls in the direction the value moved.
 */
export function NumberField({
  label,
  value,
  defaultValue,
  onValueChange,
  min = Number.MIN_SAFE_INTEGER,
  max = Number.MAX_SAFE_INTEGER,
  step = 1,
  className,
}: NumberFieldProps) {
  const id = useId();
  const clamp = (next: number) => Math.min(max, Math.max(min, next));
  const [ownValue, setOwnValue] = useState(() => clamp(defaultValue ?? 0));
  const current = clamp(value ?? ownValue);
  // The roll direction comes from the last value this field rendered, so a
  // parent that sets `value` itself still rolls the right way.
  const [shown, setShown] = useState<{ value: number; dir: Direction }>({ value: current, dir: 1 });
  if (shown.value !== current) setShown({ value: current, dir: current > shown.value ? 1 : -1 });
  const dir = shown.dir;
  // While the person types, the input shows its own text; otherwise the rolling digits show.
  const [draft, setDraft] = useState<string | null>(null);
  const reduceMotion = useReducedMotion() ?? false;

  const commit = (next: number) => {
    const clamped = clamp(next);
    setDraft(null);
    if (clamped === current) return;
    if (value === undefined) setOwnValue(clamped);
    onValueChange?.(clamped);
  };

  const commitDraft = () => {
    if (draft === null) return;
    const parsed = Number.parseInt(draft, 10);
    if (Number.isNaN(parsed)) setDraft(null);
    else commit(parsed);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    const moves = {
      ArrowUp: current + step,
      ArrowDown: current - step,
      PageUp: current + step * 10,
      PageDown: current - step * 10,
      Home: min,
      End: max,
    } satisfies Partial<Record<string, number>>;
    if (event.key === "Enter") {
      commitDraft();
      return;
    }
    if (!Object.hasOwn(moves, event.key)) return;
    // SAFETY: Object.hasOwn has just proved the key is one of the moves above.
    const next = moves[event.key as keyof typeof moves];
    event.preventDefault();
    commit(next);
  };

  const text = String(current);
  const chars = text.split("");

  return (
    <div className={cn("flex flex-col gap-2 text-sm", className)}>
      <label htmlFor={id} className="font-medium text-foreground">
        {label}
      </label>
      <div className="inline-flex w-fit items-center gap-1 rounded-full border border-border bg-background p-1 focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 focus-within:ring-offset-background">
        <button
          type="button"
          tabIndex={-1}
          aria-label="Decrease"
          disabled={current <= min}
          onClick={() => commit(current - step)}
          className={STEP_BUTTON}
        >
          <MinusGlyph />
        </button>
        {/* The span stretches to the row, so the field takes the tap at the full height of the buttons. */}
        <span className="relative flex self-stretch">
          <input
            id={id}
            type="text"
            inputMode="numeric"
            role="spinbutton"
            aria-valuenow={current}
            aria-valuemin={min === Number.MIN_SAFE_INTEGER ? undefined : min}
            aria-valuemax={max === Number.MAX_SAFE_INTEGER ? undefined : max}
            value={draft ?? text}
            onFocus={(event) => event.currentTarget.select()}
            onChange={(event) => setDraft(event.target.value.replace(/[^\d-]/g, ""))}
            onBlur={commitDraft}
            onKeyDown={handleKeyDown}
            className={cn(
              "w-20 bg-transparent text-center text-base font-medium tabular-nums text-foreground outline-none",
              draft === null && "text-transparent caret-transparent selection:bg-transparent",
            )}
          />
          {draft === null ? (
            <span
              aria-hidden="true"
              data-direction={dir}
              className="pointer-events-none absolute inset-0 flex items-center justify-center text-base font-medium tabular-nums text-foreground">
              {chars.map((char, index) => (
                // Keyed from the right, so the units digit keeps its slot when the length changes.
                <span key={chars.length - index} className="relative inline-flex overflow-hidden">
                  <AnimatePresence mode="popLayout" initial={false} custom={dir}>
                    <motion.span
                      key={char}
                      custom={dir}
                      variants={ROLL}
                      initial="enter"
                      animate="shown"
                      exit="leave"
                      transition={reduceMotion ? INSTANT : ROLL_SPRING}
                      className="inline-block"
                    >
                      {char}
                    </motion.span>
                  </AnimatePresence>
                </span>
              ))}
            </span>
          ) : null}
        </span>
        <button
          type="button"
          tabIndex={-1}
          aria-label="Increase"
          disabled={current >= max}
          onClick={() => commit(current + step)}
          className={STEP_BUTTON}
        >
          <PlusGlyph />
        </button>
      </div>
    </div>
  );
}
